const now = Date.now();                       // current time in milliseconds
const out = [];
for (const item of $input.all()) {            // every row from Get appts
  const a = item.json;
  if (a.status !== 'booked') continue;        // confirmed or cancelled: skip
  const hours = (new Date(a.start_time).getTime() - now) / 36e5;   // blank 1: which column holds the appointment time?
  let which = null;
  if (hours > 24 && hours <= 48 && !a.r48_sent) which = 'r48';
  else if (hours > 0 && hours <= 24 && !a.r24_sent) which = 'r24';
  if (which) out.push({ json: { ...a, which, hours: Math.round(hours) } });  // blank 2: what should we round?
}
return out;

const b = $json.body;                                   // Twilio's message fields
const phone = b.From.replace('whatsapp:', '');          // "whatsapp:+1..." -> "+1..."
let text = b.Body.trim().toUpperCase();                 // blank: remove spaces at both ends
text = text.replace(/[.!]+$/, '');                      // "C." -> "C"
const RULES = { CONFIRM: ['C', 'CONFIRM'], CANCEL: ['X', 'CANCEL'], TAKE: ['YES', 'Y'] };
let intent = 'UNCLEAR';                                 // default: a human looks at it
for (const [name, words] of Object.entries(RULES)) {
  if (words.includes(text)) intent = name;
}
return { json: { phone, text, raw: b.Body, intent } };
